// TreeError returns ErrParseTree if the grammar could not parse the tree
// cleanly, and nil otherwise. A chunker returns its chunks together with
// TreeError(tree), so the fallback wrapper can keep what the walk found and
// window the lines it missed, rather than pass a partial file off as whole.
func TreeError(tree *gotreesitter.Tree) error {
	if tree.RootNode().HasError() || tree.ParseStoppedEarly() {
		return fmt.Errorf("%w (stop reason %v)", ErrParseTree, tree.ParseStopReason())
	}
	return nil
}

// Defends AC2 at its source: a tree with an error node used to yield whatever
// nodes the walk happened to find, so a broken file indexed as a partial (or
// empty) set of chunks and nothing said so.
func TestTreeError_ReportsATreeWithAnErrorNode(t *testing.T) {
	lang := NewPythonChunker().lang
	tree, err := ParseSource([]byte(brokenPython), lang)
	if err != nil {
		t.Fatalf("ParseSource(broken): %v", err)
	}
	if err := TreeError(tree); !errors.Is(err, ErrParseTree) {
		t.Errorf("TreeError(broken) = %v, want ErrParseTree", err)
	}
	tree.Release()

	tree, err = ParseSource([]byte(cleanPython), lang)
	if err != nil {
		t.Fatalf("ParseSource(clean): %v", err)
	}
	if err := TreeError(tree); err != nil {
		t.Errorf("TreeError(clean) = %v, want nil", err)
	}
	tree.Release()
}

// ParseSource parses source bytes with the given language and returns the tree.
// The caller must call tree.Release() when done.
func ParseSource(content []byte, lang *gotreesitter.Language) (*gotreesitter.Tree, error) {
	parser := gotreesitter.NewParser(lang)
	return parser.Parse(content)
}

func (c *CSharpChunker) Chunk(path string, content []byte) ([]semantic.Chunk, error) {
	tree, err := ParseSource(content, c.lang)
	if err != nil {
		return nil, err
	}
	defer tree.Release()

	var chunks []semantic.Chunk
	root := tree.RootNode()
	leaked := c.walkNode(root, root, content, path, &chunks)
	if err := TreeError(tree); err != nil {
		return chunks, err
	}
	if leaked != "" {
		// gotreesitter can recover an unclosed declaration into a tree with no
		// ERROR node that has dropped earlier declarations, leaving one of the
		// grammar's hidden (underscore) rules in their place. That tree is not
		// a clean parse, whatever HasError says.
		return chunks, fmt.Errorf("%w (hidden node %s in tree)", ErrParseTree, leaked)
	}
	return chunks, nil
}

// Defends against the README language table drifting from RegisterAllChunkers:
// an extension registered without a row (or a row for one that is not
// registered) fails, and only Go, JavaScript, TypeScript and Python may claim call edges.
func TestReadmeLanguageTable_MatchesRegisteredExtensions(t *testing.T) {
	factory := semantic.NewChunkerFactory()
	RegisterAllChunkers(factory)
	registered := map[string]bool{}
	for _, e := range factory.SupportedExtensions() {
		registered[e] = true
	}

	table := parseReadmeLanguageTable(t)

	var missing, extra []string
	for e := range registered {
		if _, ok := table[e]; !ok {
			missing = append(missing, e)
		}
	}
	for e := range table {
		if !registered[e] {
			extra = append(extra, e)
		}
	}
	sort.Strings(missing)
	sort.Strings(extra)
	if len(missing) > 0 {
		t.Errorf("registered but missing from README language table: %v", missing)
	}
	if len(extra) > 0 {
		t.Errorf("in README language table but not registered: %v", extra)
	}

	edgeExts := map[string]bool{"go": true, "js": true, "jsx": true, "mjs": true, "cjs": true,
		"py": true, "pyi": true, "pyw": true, "ts": true, "tsx": true, "mts": true, "cts": true}
	for e, edges := range table {
		want := "no"
		if edgeExts[e] {
			want = "yes"
		}
		if edges != want {
			t.Errorf(".%s call edges = %q in README, want %q", e, edges, want)
		}
	}
}

func TestRegisteredCommands_MatchesTheRegistry(t *testing.T) {
	// RegisteredCommands is what the tool-definition audit checks against. If it
	// drifted from commandRegistry the audit would pass while the server was
	// advertising something it cannot run.
	got := RegisteredCommands()
	if len(got) != len(commandRegistry) {
		t.Fatalf("RegisteredCommands returned %d names for %d registry entries", len(got), len(commandRegistry))
	}
	for _, name := range got {
		if _, ok := commandRegistry[name]; !ok {
			t.Errorf("RegisteredCommands returned %q, which is not in the registry", name)
		}
	}
}

func TestKotlinChunker_NamelessDeclarationIsDropped(t *testing.T) {
	// The name guard: a node without an identifier must not become a chunk.
	c := NewKotlinChunker()
	src := []byte("package a\n")
	tree, err := ParseSource(src, c.lang)
	if err != nil {
		t.Fatal(err)
	}
	defer tree.Release()
	var out []semantic.Chunk
	c.extractType(tree.RootNode(), tree.RootNode(), src, "a.kt", &out)
	c.extractFunction(tree.RootNode(), tree.RootNode(), src, "a.kt", &out, false)
	if len(out) != 0 {
		t.Errorf("emitted chunks for nameless nodes: %+v", out)
	}
}

func TestRegisterAllChunkers(t *testing.T) {
	// This test verifies that RegisterAllChunkers registers chunkers for all expected extensions.
	// Previously, index.go and index_update.go had duplicated registration code.
	// Now they share RegisterAllChunkers to ensure consistency.
	factory := semantic.NewChunkerFactory()
	RegisterAllChunkers(factory)

	exts := factory.SupportedExtensions()
	extSet := make(map[string]bool)
	for _, ext := range exts {
		extSet[ext] = true
	}

	// Required extensions from each chunker type
	requiredExtensions := []struct {
		ext   string
		descr string
	}{
		{"go", "GoChunker"},
		{"js", "JSChunker"},
		{"ts", "JSChunker"},
		{"py", "PythonChunker"},
		{"php", "PHPChunker"},
		{"rs", "RustChunker"},
		{"md", "MarkdownChunker"},
		{"markdown", "MarkdownChunker"},
		{"html", "HTMLChunker"},
		{"htm", "HTMLChunker"},
		{"txt", "GenericChunker"},
		{"yaml", "GenericChunker"},
	}

	for _, req := range requiredExtensions {
		if !extSet[req.ext] {
			t.Errorf("RegisterAllChunkers should register %q extension (from %s)", req.ext, req.descr)
		}
	}

	// Verify we have a reasonable number of extensions
	if len(exts) < 15 {
		t.Errorf("Expected at least 15 registered extensions, got %d", len(exts))
	}
}

func (c *KotlinChunker) Chunk(path string, content []byte) ([]semantic.Chunk, error) {
	tree, err := ParseSource(content, c.lang)
	if err != nil {
		return nil, err
	}
	defer tree.Release()

	var chunks []semantic.Chunk
	c.walk(tree.RootNode(), content, path, &chunks, "")
	return chunks, TreeError(tree)
}
